) AS (
  VALUES 
    (411::BIGINT, 'El profe es muy buena gente. El curso es muy chiva y el profe no lo complica de más. Lástima que ya este semestre se pensionó.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '43455b47d476cb573b7dde24c144c4c99999907d2508c9d0f7f501d75a130ac0'::TEXT, ARRAY[1321]::BIGINT[]),
    (411::BIGINT, 'Es un profe con edad bastante avanzada por lo cual cuenta con un conocimiento enorme para enseñar, es muy alegre durante la clase. Si puede llevar lab con él no lo dude.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'de99dc8c2c69bf4fcded29e1c733fe3846ce8efe32e5aa84e6266df726d810f6'::TEXT, ARRAY[1321]::BIGINT[]),
    (411::BIGINT, 'Aprovechen a interiano antes de que se pensione'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'ec2d71c684e19eef2d22a87ef7436811c0d3e72375319f646a26a54cd9a2ee14'::TEXT, ARRAY[1321]::BIGINT[]),
    (411::BIGINT, 'El profe sabe mucho, pero a veces cuesta entenderle algunas cosas. Se preocupa por ayudar a los estudiantes y es muy comprensivo con los tiempos de entrega. No dio ninguna nota hasta semana 19. En general, es un buen profe, matricule con el sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas']::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, '08e84915433b85b35fb26269d06ad582b778a979759e3c42340874b6e89774f6'::TEXT, ARRAY[1321]::BIGINT[]),
    (411::BIGINT, 'El curso de control automático es duro por si solo, es pesado y hay mucha materia, los exámenes son más duros que la materia de las presentaciones pero si las estudia bien si se puede. Tiene que estudiar bien.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'c4718332f1d0f4e854749d3246963d6326bfe4a87b380bec783e097baa48564b'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'El profe es muy buena gente y siempre está dispuesto a ayudar. La materia de Control es pesada, por lo que es mejor llevarla al día. Sus presentaciones están muy completas, en el examen la dificultad es un poco mayor, pero nada del otro mundo'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '35b642489521c739f5021b3ac6a12b1979355756ff1e31692ec95e03b8dffae1'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'En la teoría, es pesada y la clase es larga, intente mantener todo al día y entender bien la materia, repase con exámenes pasados si es posible. El lab se pasa si o si, mientras asista y haga las cosas, el lo ayuda siempre, reparte teja parejo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'b9263882e0bdee9cf8175d0b482f98fac9d0c0498f93fd530232468f2b3c00fa'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'No matricule con el'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico']::TEXT[], '2022-05-25T00:00:00+00:00'::TIMESTAMPTZ, '52b8fd6cba71833e8732a91da644e58051392af51b1f82397d2f7812582c65ca'::TEXT, ARRAY[1321]::BIGINT[]),
    (411::BIGINT, 'Es buen profe, no es la clase más divertida, pero las tiene grabadas lo cual sirve mucho, las presentaciones están super completas, hay muchos examenes de práctica y quices en la página del profe. Los exámenes son en forms por lo que solo se califica la respuesta final'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-23T00:00:00+00:00'::TIMESTAMPTZ, '66912c895858f493d7bdd3e91d85260fc8cfb96e7abe83b0c0840cc67ae973dc'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'Las clases son aburridas. Hace quices TODAS las semanas y de dificultad elevada. Los exámenes son en Forms y solo evalúa la respuesta.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos exámenes']::TEXT[], '2021-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'a442f9fe3910f0a066bfa78d41e687a426df096c40fcea823a340254850a6e7e'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'muy mal profesor. se quedó medio rezagado en su época de estudio en alemania. aburrididimo'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, '510807782eff26542e5e89d5b15727fe83b64591b7047d97a1316b61771c84a3'::TEXT, ARRAY[1321]::BIGINT[]),
    (411::BIGINT, 'Pues es el menos malo de los que da el curso, pero eso no lo hace bueno la verdad'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '743a4d0aab6ff37bcf7c3c1a660be618879c078c2a0aceadf8134222ab73b66a'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Clases largas']::TEXT[], '2021-05-12T00:00:00+00:00'::TIMESTAMPTZ, '22bdc643513ab8c687a1fec38025ee705c1cb74ce4e733a053b0dbc7c748e254'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'Es de los típicos profes que les gusta embarrialar la cancha en los exámenes. Los quices son casi sorpresa, porque avisa "a medias". Aveces hace cambios en la rúbrica de evaluación, aún cuando no todos están de acuerdo. La rúbrica de evaluación de las tareas es confusa.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '5755afc6a73567c8b5321baa3d12367f60664099966a5819c7a230c5578e5bb6'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'Clases aburridas y algo confuso, profe regular'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura']::TEXT[], '2021-01-30T00:00:00+00:00'::TIMESTAMPTZ, '08e82f13e155c954946e66820b6da7b6617ea862d15cbf84b506ea88fa1d45d7'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'Explica claro pero las clases son bastante aburridas y cuesta poner atención. En modalidad virtual recomiendo poner las grabaciones a velocidad x1.5 o x1.75, solo así logré no dormirme con el tono de voz del mae.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-27T00:00:00+00:00'::TIMESTAMPTZ, '26cf3d7de6fb28d001ad8d38a5a77d167fbd0016818f4ad396a9ac7a7b86fd98'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'Buen profesor, sabe mucho de control y se esfuerza en dar las clases y porque uno entienda. Atiende todas las dudas que uno tenga. Hay que levar la materia al día para evitar confundirse. El tono de voz lo duerme a uno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '45a5fe6a7443a90cd75408401d4251e0f586a3d02d422bac43e61429412a9d10'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'Se esfuerza por dar la clase bien, ya que las graba entonces es super util verla de nuevo, revise los quices y examenes pasados en la pagina. Super recomendado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Clases excelentes']::TEXT[], '2020-08-12T00:00:00+00:00'::TIMESTAMPTZ, '76e1b0d6db92a131b1da3fdf5c40fc80ac6057375019efcd5bf95f938e721fd2'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'Creo que el profe se adaptó bien a la virtualidad, es importante escuchar sus clases para responder algunas preguntas del examen. Es todo un reto no dormirse, pero por lo menos ahora están en youtube las clases y uno repite la parte donde se durmió. En general es bueno y sabe de lo que habla.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'd29c96864909441e1995b1d1fd05c9ce15d5b66c6eeb0291cc602359423135ca'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'La materia es complicada, pero este profesor no ayuda. Incluso si uno le pregunta en consulta, es dificil entender, y habla mucho respondiendote. Sabe mucho de control, por lo que sirve mucho preguntarle cosas para el lab. Las tareas son dificiles, pero pone 100 si se VEN completas.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '03db7009abd18e8f59eb40996613cd44d46b0af76f8ef2c31fd2905ad78a43f8'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'Para lab creo que es uno de los mejores profesores. Ayuda bastante cuando uno va a consulta y da tiempo extra y posibilidad de mejorar resultados si a uno le va mal en algo. Toma en cuenta el esfuerzo cuando se hace el proyecto principal'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'c9941db12170a7ba68c1a106355cea15b26d57bcf43ab4caf0a1771c562b5612'::TEXT, ARRAY[1321]::BIGINT[]),
    (411::BIGINT, 'Las clases son lo más aburrido del mundo. En las explicaciones es muy bueno y califica muy suave. Siempre está atento a consultas aunque en las mismas se emociona demasiado hablando de muchos temas (cada consulta puede durar hasta más de 30 minutos). Deja llevar apuntes para los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '0a2662544743d2e00ce4134363eeb4495525d614973a176bde7872f506de7670'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'Curso super malo, profe peor. #obviosi #confesionesTEC'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-08-21T00:00:00+00:00'::TIMESTAMPTZ, '8b47296027975d73f4bfda7da4e988951bbf7153f3ee195faa321d4a19be2489'::TEXT, ARRAY[1255, 1252, 1340]::BIGINT[]),
    (411::BIGINT, 'Es excelente profesor, clases amenas, no exige mucho, es claro al explicar y las clases son entretenidas con los proyectos, la asistencia es muy importante pero siempre permite justificarse , ayuda con apoyo y hace bien la función de introducir la ingeniería electrónica.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '1160fc8e2c796746c6258f6c2fe8e5b07e8f76508992c6306d2540dfdd0fa588'::TEXT, ARRAY[1252]::BIGINT[]),
    (411::BIGINT, 'clases en extremo aburridas, el profe solo va a leer lo que dicen las presentaciones, lo bueno es que el material de la pagina del porfe esta bien ordenado y es fácil estudiar por cuenta propia'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '705ef06741fd31d4731628ea99561c8e00614e26a7ff32a3493af7c77c31066d'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'La clase es muy aburrida e ir no ayuda de mucho. Califica normal y muchas de las evaluaciones son un misterio hasta la ultima semana del semestre. Dejo las 2 tareas del curso hasta el puro final pero practicamente las regalo. Al menos es buena gente la mayoria de las veces'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '75aa7b0a47e46dc17778bc8e4d37a8c3db0ed8e05dc13b67e30e1bf4897ab29f'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'Un curso malo...como de kinder. acer proyectos de cartón y paletas a éstas alturas Pero el curso es sólo de asistencia'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-06T00:00:00+00:00'::TIMESTAMPTZ, '42dd12a7171daf3cf330b96320121d05e4d47b06e776732d49d7fd4883a1bd6a'::TEXT, ARRAY[1252]::BIGINT[]),
    (411::BIGINT, 'con solo ir se pasa, el profe es suuper aburrido'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-03T00:00:00+00:00'::TIMESTAMPTZ, '5e8b0dedae0dbb425d85ce3c5ecd0f8f1b3ff77630defeba7679039e12656abf'::TEXT, ARRAY[1255, 1252, 1340]::BIGINT[]),
    (411::BIGINT, 'Las clases son super aburridas pero los exámenes y quices son con el mismo formato de semestres anteriores, por lo que con practicar eso, es fácil salir bien'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, '8a0ee81e97755a84aa0aa08fcbbd08dfd0eaf272eead35be21b32c38b0f0ff67'::TEXT, ARRAY[1316]::BIGINT[]),
    (411::BIGINT, 'Un curso que se pasa con asistencia. El profe tiene interés en la materia y explica algunas cosas y otras no.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-11T00:00:00+00:00'::TIMESTAMPTZ, '234cb866b91760d6bb6ed7ac2cbd16b9ddb8573c10c3e6b07027cb6235d4ae67'::TEXT, ARRAY[1255]::BIGINT[]),
    (411::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-18T00:00:00+00:00'::TIMESTAMPTZ, '03150fba1d514ffad45e114e55157f870cae1da644af68b0dcc6e57ecc06f7e7'::TEXT, ARRAY[1321]::BIGINT[]),
    (411::BIGINT, 'Solo con asistir se pasa, además es cómico.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '9b3ddbbdde0ebe0ebb3e46bdf7c62db54b32ad33ed030629cb8b3acf82377e56'::TEXT, ARRAY[1252]::BIGINT[]),
    (411::BIGINT, 'Super facil con solo ir se pasa, las clases son entretenidas y trata de explicar lo mejor que puede, recomendado.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e85a7832dbde59c9e605f846f74305cb32db8be813681c9c5447d5024c876db6'::TEXT, ARRAY[1252]::BIGINT[]),
    (411::BIGINT, 'el curso solo se pasa con asistencia, y no es que sea facil es que asi es el curso, pero el profe trata de explicar lo mas que pueda aunque a veces no es muy claro'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'cbce77c04be3ed353208bd838fc57b54fae6b41e664db1c598740ce69d309dd4'::TEXT, ARRAY[1252]::BIGINT[]),
    (411::BIGINT, 'Es un profe bastante gracioso e interesante, es un profe recomendable, al menos para este curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-04T00:00:00+00:00'::TIMESTAMPTZ, '12d39099922a356b051ee69839bcf1c752ac8003e6d34ebc733c6710431da42e'::TEXT, ARRAY[1252]::BIGINT[]),
    (411::BIGINT, 'Malo, no sé le ocurra llevarle la contraria. Cree tener la verdad absoluta'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-01T00:00:00+00:00'::TIMESTAMPTZ, '2e83632af46110b38902dc3964f974d2945da8bbd8b605dfa99b50ebdd836580'::TEXT, ARRAY[1321]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
